#!/usr/bin/env python3
import pathlib, sys
lines=sys.stdin.read().splitlines()
if not lines or lines[0] != '*** Begin Patch': raise SystemExit('missing Begin Patch')
i=1
while i < len(lines):
    if lines[i] == '*** End Patch': break
    if lines[i].startswith('*** Update File: '):
        path=pathlib.Path(lines[i].split(': ',1)[1]); i+=1
        text=path.read_text(); hunks=[]
        while i < len(lines) and not lines[i].startswith('*** '):
            if not lines[i].startswith('@@'): raise SystemExit(f'expected hunk, got {lines[i]}')
            i+=1; h=[]
            while i < len(lines) and not lines[i].startswith('@@') and not lines[i].startswith('*** '): h.append(lines[i]); i+=1
            hunks.append(h)
        for h in hunks:
            old='\n'.join(x[1:] for x in h if x.startswith((' ','-')))
            new='\n'.join(x[1:] for x in h if x.startswith((' ','+')))
            if old not in text: raise SystemExit(f'hunk not found in {path}: {old[:120]!r}')
            text=text.replace(old,new,1)
        path.write_text(text)
    elif lines[i].startswith('*** Add File: '):
        path=pathlib.Path(lines[i].split(': ',1)[1]); i+=1; content=[]
        while i < len(lines) and not lines[i].startswith('*** '):
            line=lines[i]
            if not line.startswith('+'): raise SystemExit(f'bad add line: {line}')
            content.append(line[1:]); i+=1
        path.parent.mkdir(parents=True,exist_ok=True); path.write_text('\n'.join(content)+'\n')
    else: raise SystemExit(f'unknown directive {lines[i]}')
